import { Link } from 'react-router-dom'

import FavoriteIcon from '@mui/icons-material/Favorite'
import { Box, Card, CardActionArea, CardMedia, Chip, Stack, Typography, useMediaQuery, useTheme } from '@mui/material'

import { getDDay } from 'src/utils/Deadline'
import getImgFromHtml from 'src/utils/getImgFromHtml'
import getRecruitDDayLabel from 'src/utils/getRecruitDDayLabel'
import { htmlToPlainTextWithDOM } from 'src/utils/htmlToPlainText'

import { type Recruit } from 'src/models/recruit'

interface RecruitNoticePreviewProps {
  recruit: Recruit
  showClubInfo?: boolean
}

const today = new Date()

const RecruitNoticePreview = ({ recruit, showClubInfo = true }: RecruitNoticePreviewProps) => {
  const theme = useTheme()
  const isNotMobile = useMediaQuery(theme.breakpoints.up('sm'))
  const dDay = recruit.endAt ? getDDay(recruit.endAt) : undefined
  const startAtDate = new Date(recruit.startAt)
  const endAtDate = recruit.endAt ? new Date(recruit.endAt) : null
  const isBeforeDeadline = endAtDate ? today <= endAtDate : true
  const isRecruiting = startAtDate <= today
  const recruitImgSrc = getImgFromHtml(recruit.contents) || ''

  return (
    <Card>
      <CardActionArea
        component={Link}
        to={`/club/${recruit.clubId}/recruit/${recruit.id}`}
        sx={{ display: 'flex', flexDirection: 'column', alignItems: 'stretch', padding: 2 }}
      >
        <Stack direction="row" flex="1" justifyContent="space-between" alignItems="stretch">
          <Stack direction="column" spacing={1} sx={{ height: 180, minWidth: 0, flex: 1 }}>
            {showClubInfo && (
              <Stack>
                <Typography
                  fontSize={15}
                  fontWeight={'bold'}
                  sx={{
                    color: 'text.primary',
                    overflow: 'hidden',
                    textOverflow: 'ellipsis',
                    whiteSpace: 'nowrap'
                  }}
                >
                  {recruit.clubName}
                </Typography>
                <Typography
                  fontSize={14}
                  color="text.secondary"
                  sx={{
                    overflow: 'hidden',
                    textOverflow: 'ellipsis',
                    whiteSpace: 'nowrap'
                  }}
                >
                  {recruit.clubDescription ?? ''}
                </Typography>
                <Stack direction="row" spacing={1} marginTop={1}>
                  <Chip
                    label={recruit.categoryMain}
                    size="small"
                    sx={{ padding: 0.5, fontSize: isNotMobile ? 13 : 11, paddingTop: 0.7 }}
                  />
                  <Chip
                    label={recruit.belonging}
                    size="small"
                    sx={{ padding: 0.5, fontSize: isNotMobile ? 13 : 11, paddingTop: 0.7 }}
                  />
                </Stack>
              </Stack>
            )}
            <Box
              overflow="hidden"
              textOverflow="ellipsis"
              sx={{
                display: '-webkit-box',
                WebkitLineClamp: 1,
                WebkitBoxOrient: 'vertical',
                whiteSpace: 'normal'
              }}
            >
              <Typography fontSize={15} fontWeight={'bold'}>
                {recruit.title}
              </Typography>
            </Box>
            <Box
              overflow="hidden"
              textOverflow="ellipsis"
              sx={{
                display: '-webkit-box',
                WebkitLineClamp: showClubInfo ? 2 : 4,
                WebkitBoxOrient: 'vertical',
                whiteSpace: 'normal'
              }}
            >
              <Typography>{htmlToPlainTextWithDOM(recruit.contents)}</Typography>
            </Box>
          </Stack>
          {recruitImgSrc && (
            <CardMedia
              sx={{
                width: 144,
                minWidth: 144,
                maxWidth: 144,
                height: 180,
                objectFit: 'cover',
                objectPosition: 'center',
                marginLeft: 2,
                borderRadius: 0.5
              }}
              component="img"
              image={recruitImgSrc}
            ></CardMedia>
          )}
        </Stack>
        <Stack direction="row" alignItems="center" spacing={1}>
          <Chip
            label={isBeforeDeadline ? (isRecruiting ? '모집중' : '모집예정') : '모집종료'}
            size="small"
            variant={isBeforeDeadline && isRecruiting ? 'filled' : 'outlined'}
            color={isBeforeDeadline ? 'primary' : 'default'}
            sx={{
              padding: 0.5,
              fontSize: isNotMobile ? 13 : 11,
              paddingTop: 0.7
            }}
          />
          {isBeforeDeadline && (
            <Typography variant="body2" fontSize={15} color={theme.colors.primary.main} fontWeight="bold">
              {getRecruitDDayLabel(dDay)}
            </Typography>
          )}
          <FavoriteIcon
            sx={{
              width: '0.6em',
              height: '0.6em',
              color: theme.colors.alpha.black[30]
            }}
          />
          <Typography variant="body2" fontSize={15} color={theme.colors.alpha.black[30]} marginLeft={0.2}>
            {recruit.likeCount}
          </Typography>
        </Stack>
      </CardActionArea>
    </Card>
  )
}

export default RecruitNoticePreview
